// AUDITED GAME FLOW PATCH — 2026-11-23
// Only changes presentation/turn timing, not archived broadcast art or raw game assets.
const flipTile=(s,face,em='')=>`<div class="round-flip ${s==='back'?'is-back':''}"><small>${em}</small><strong>${face}</strong></div>`;
const roundFrame=(kicker,title,inner,buttons)=>`<section class="round-frame"><div class="round-kicker">${kicker}</div><h2>${title}</h2><div class="round-flip-row">${inner}</div><div class="round-controls">${buttons}</div></section>`;

// 연승게임: reveal before adjusting streak. The bot opponent's own table is also revealed.
const _initStreakOriginal=initStreak;
initStreak=function(){_initStreakOriginal();st.phase='choose';st.duel=null};
streakMove=function(n){if(finishText||st.phase!=='choose')return;st.duel={me:n,opp:randint(3),bot:randint(3),rival:randint(3)};st.phase='sealed';render()};
function streakReveal(){if(st.phase!=='sealed')return;st.phase='reveal';render()}
function streakSettle(){if(st.phase!=='reveal')return;let d=st.duel,a=rpsWin(d.me,d.opp),b=rpsWin(d.bot,d.rival);st.now[0]=a===1?st.now[0]+1:0;st.now[1]=b===1?st.now[1]+1:0;st.max[0]=Math.max(st.max[0],st.now[0]);st.max[1]=Math.max(st.max[1],st.now[1]);st.duel.result=a===1?'승리':a===0?'비김':'패배';logit(`${st.guest[st.round]}: 나 ${rpsNames[d.me]} / 관전자 ${rpsNames[d.opp]} → ${st.duel.result} · 내 연승 ${st.now[0]}`);st.phase='result';render()}
function streakNext(){if(st.phase!=='result')return;st.round++;if(st.round===11){finish(st.max[0]===st.max[1]?null:st.max[0]>st.max[1],`최장 연승 나 ${st.max[0]} : AI ${st.max[1]}`)}else{st.phase='choose';st.duel=null}render()}
drawStreak=function(){const d=st.duel;let match=d?roundFrame(`관전자 ${st.round+1} / 11`,st.phase==='sealed'?'선택 완료 — 동시 공개 대기':st.phase==='reveal'?'양쪽 선택 공개':'승부 결과',flipTile(st.phase==='sealed'?'back':'front',st.phase==='sealed'?'?':rpsNames[d.me],'나')+`<span class="round-vs">VS</span>`+flipTile(st.phase==='sealed'?'back':'front',st.phase==='sealed'?'?':rpsNames[d.opp],'관전자')+(st.phase==='reveal'||st.phase==='result'?`<div class="round-secondary">AI 도전자 ${rpsNames[d.bot]} · 상대 ${rpsNames[d.rival]}${st.phase==='result'?' · 내 결과 '+d.result:''}</div>`:''),st.phase==='sealed'?action('동시에 공개','streakReveal()'):st.phase==='reveal'?action('승패 확인·점수 반영','streakSettle()'):action(st.round===10?'최종 결과':'다음 관전자','streakNext()')):'';stage(`${exBar([`${Math.min(st.round+1,11)}/11 관전자`,`내 현재 연승 ${st.now[0]}`])}${scores(['내 최장 연승','AI 최장 연승'],st.max)}${st.phase==='choose'?`<div class="info">${st.guest[st.round]}와 대결합니다. 가위·바위·보를 골라 제출하세요.</div><div class="round-choice">${rpsNames.map((x,i)=>action(x,`streakMove(${i})`)).join('')}</div>`:match}`,`<p class="muted">관전자와의 선택을 공개한 뒤 판정합니다. AI 도전자도 별도로 관전자와 대결합니다.</p><p class="small">게임 세부 참가자 행동과 관전자 조력은 규칙 기반 AI로 단순화했습니다.</p>`) };

// 1·2·3 게임: separate hidden-card submission and reveal from points/round progression.
const _init123Original=init123;
init123=function(){_init123Original();st.phase='choose';st.duel=null};
move123=function(){if(finishText||st.phase!=='choose'||!st.hands[0].includes(st.card))return;let op=st.opp;if(!st.hands[op]?.length)op=st.hands.findIndex((h,i)=>i&&h.length);if(op<1)return;st.duel={op,my:st.card,theirs:pick(st.hands[op])};st.phase='sealed';render()};
function reveal123(){if(st.phase!=='sealed')return;st.phase='reveal';render()}
function settle123(){if(st.phase!=='reveal')return;let {op,my,theirs}=st.duel;st.hands[0].splice(st.hands[0].indexOf(my),1);st.hands[op].splice(st.hands[op].indexOf(theirs),1);if(my>theirs)st.points[0]++;else if(my<theirs)st.points[op]++;st.duel.outcome=my>theirs?'내 승리':my<theirs?'AI 승리':'무승부';logit(`나 ${my} / AI ${op} ${theirs} → ${st.duel.outcome}`);let bots=shuffle(Array.from({length:12},(_,i)=>i+1).filter(i=>i!==op&&st.hands[i].length));for(let j=0;j+1<bots.length;j+=2){let a=bots[j],b=bots[j+1],v=pick(st.hands[a]),w=pick(st.hands[b]);st.hands[a].splice(st.hands[a].indexOf(v),1);st.hands[b].splice(st.hands[b].indexOf(w),1);if(v>w)st.points[a]++;else if(w>v)st.points[b]++}st.round++;st.phase='result';render()}
function next123(){if(st.phase!=='result')return;st.duel=null;if(!st.hands[0].includes(st.card))st.card=st.hands[0][0]||1;if(!st.hands[0].length||st.round>=35||st.hands.slice(1).every(x=>!x.length)){let ranking=st.points.map((n,i)=>st.hands[i].length?0:n),max=Math.max(...ranking);finish(ranking[0]===max&&ranking.filter(x=>x===max).length===1,`내 최종 ${ranking[0]}점 · 1위 ${st.people[ranking.indexOf(max)]}(${max}점)`)}else st.phase='choose';render()}
const _trade123Original=trade123;
trade123=function(){if(st.phase!=='choose')return;_trade123Original()};
draw123=function(){let opts=st.people.map((p,i)=>({p,i,n:st.hands[i].length})).filter(x=>x.i&&x.n),d=st.duel;let hands=`<div class="label">내 숫자 카드</div><div class="round-choice">${[1,2,3].map(n=>`<button class="tile ${st.card===n?'selected':''}" ${!st.hands[0].includes(n)||!!finishText?'disabled':''} onclick="st.card=${n};render()">${n} <small>×${st.hands[0].filter(x=>x===n).length}</small></button>`).join('')}</div><div class="toolbar"><select id="op123" class="inp" onchange="st.opp=Number(this.value)">${opts.map(x=>`<option value="${x.i}" ${st.opp===x.i?'selected':''}>${x.p} · ${x.n}장</option>`).join('')}</select>${action('카드 제출','move123()',!st.hands[0].length||!opts.length)}${action('교환 제안','trade123()',!opts.length,'alt')}</div>`;let match=d?roundFrame(`카드 대결 / AI ${d.op}`,st.phase==='sealed'?'서로 비공개로 제출했습니다':st.phase==='reveal'?'숫자 카드 동시 공개':d.outcome,flipTile(st.phase==='sealed'?'back':'front',st.phase==='sealed'?'?':d.my,'나')+`<span class="round-vs">VS</span>`+flipTile(st.phase==='sealed'?'back':'front',st.phase==='sealed'?'?':d.theirs,`AI ${d.op}`),st.phase==='sealed'?action('카드 공개','reveal123()'):st.phase==='reveal'?action('판정하고 점수 반영','settle123()'):action('다음 대결','next123()')):'';stage(`${exBar([`남은 카드 ${st.hands[0].length}장`,`전체 참가자 13명`])}${scores(['내 승점','최고 AI 승점'],[st.points[0],Math.max(...st.points.slice(1))])}${st.phase==='choose'?`<div class="info">상대 AI를 고르고 숫자 카드 1장을 제출하세요. 양쪽 카드를 공개한 후 점수가 반영됩니다.</div>${hands}`:match}`,`<div class="log">${st.people.map((p,i)=>`<div>${p}: ${st.points[i]}점 · 카드 ${st.hands[i].length}장</div>`).join('')}</div><p class="small">실제 협상·양도는 간소화한 1인 AI 모드입니다.</p>`) };

// 인디언 포커: Showdown must be visible before next hand is dealt.
// Keep settled chips while cards are on screen. Only user action triggers next hand.
const _initPokerOriginal=initPoker;
initPoker=function(){_initPokerOriginal();st.phase=st.phase||'bet'};
pokerDeal=function(){if(st.chips.some(x=>x<1)){finish(st.chips[0]>st.chips[1],`보유 칩: 나 ${st.chips[0]} / AI ${st.chips[1]}`);st.phase='finished';return}if(st.deck.length<2)st.deck=shuffle(Array.from({length:10},(_,i)=>[i+1,i+1]).flat());st.round++;st.cards=[st.deck.pop(),st.deck.pop()];st.chips[0]--;st.chips[1]--;st.contrib=[1,1];st.pot=st.carry+2;st.carry=0;st.checks=0;st.raises=0;st.phase='bet';st.reveal=null;st.turn=(st.round+1)%2;logit(`${st.round}번째 판 시작, 기본 칩 1씩 제출`);if(st.turn===1)pokerAI()};
pokerFold=function(who){let other=1-who,pot=st.pot;st.chips[other]+=pot;let penalty=st.cards[who]===10?Math.min(10,st.chips[who]):0;st.chips[who]-=penalty;st.chips[other]+=penalty;st.reveal={kind:'fold',cards:[...st.cards],who,pot,penalty,summary:`${who===0?'내가':'AI가'} 다이 · ${other===0?'나':'AI'} ${pot}칩 획득`};st.pot=0;st.phase='showdown';logit(`${st.reveal.summary}${penalty?' · 10카드 벌금 '+penalty+'칩':''}`)};
pokerShowdown=function(){let [a,b]=st.cards,pot=st.pot;if(a>b)st.chips[0]+=pot;else if(b>a)st.chips[1]+=pot;else st.carry+=pot;st.reveal={kind:'showdown',cards:[a,b],pot,summary:`나 ${a} / AI ${b} → ${a>b?'내 승리':a<b?'AI 승리':'무승부 (팟 이월)'}`};st.pot=0;st.phase='showdown';logit(st.reveal.summary)};
const _pokerActOriginal=pokerAct;
pokerAct=function(type,amt=0){if(st.phase!=='bet')return;_pokerActOriginal(type,amt)};
function pokerNext(){if(st.phase!=='showdown')return;pokerDeal();render()}
drawPoker=function(){let d=st.contrib[1]-st.contrib[0],settled=st.phase==='showdown',r=st.reveal;let cards=settled?`<div class="round-flip-row">${flipTile('front',r.cards[0],'내 카드')}<span class="round-vs">VS</span>${flipTile('front',r.cards[1],'AI 카드')}</div>`:`<div class="round-flip-row">${flipTile('front',st.cards[1],'AI 이마 카드')}<span class="round-vs">VS</span>${flipTile('back','?','내 이마 카드')}</div>`;stage(`${exBar([`${st.round}번째 판`, `팟 ${settled?r.pot:st.pot}칩`, `남은 덱 ${st.deck.length}장`])}${scores(['내 칩','AI 칩'],st.chips)}<section class="round-frame"><div class="round-kicker">${settled?'SHOWDOWN · 판정 공개':'BETTING · 베팅 중'}</div><h2>${settled?txt(r.summary):'상대의 카드만 보고 선택하세요'}</h2>${cards}${settled?`<div class="info">${r.kind==='fold'?'폴드 후 카드 확인':r.summary}${r.penalty?' · 10카드 벌금 '+r.penalty+'칩':''} · 정산된 칩을 확인하세요.</div><div class="round-controls">${action('다음 판 배분','pokerNext()')}</div>`:`<div class="info">${d?d+'칩을 맞추거나 다이하세요.':'체크·레이즈·다이 중 선택하세요.'}</div><div class="round-controls">${action(d?`콜 ${d}칩`:'체크',"pokerAct('call')",d>st.chips[0])}${action('레이즈 +1',"pokerAct('raise',1)",d+1>st.chips[0]||st.raises>=4,'blue')}${action('레이즈 +3',"pokerAct('raise',3)",d+3>st.chips[0]||st.raises>=4,'blue')}${action('다이',"pokerAct('fold')",false,'red')}</div>`}</section>`,`<div class="info">매 판 기본 베팅 1칩 · 더 큰 카드가 승리합니다. 동점이면 팟 이월. 다이한 카드가 10이면 벌금 10칩입니다.</div>${scores(['내 판 베팅','AI 판 베팅'],st.contrib)}`)};

// 4인 3목: AI 3명 should be seen taking turns one at a time.
let ttSession=0;
const _ttInitOriginal=ttInit;
ttInit=function(){ttSession++;_ttInitOriginal();st.turn=0};
ttMove=function(i){if(finishText||st.turn!==0||st.board[i]!==-1)return;st.board[i]=0;if(ttWinner(st.board,i,0)){finish(true,'세 돌 연결 성공');render();return}if(st.board.every(v=>v!==-1)){finish(null,'25칸이 모두 찼습니다.');render();return}st.turn=1;render();const session=ttSession;setTimeout(()=>ttAIPlace(1,session),500)};
function ttAIPlace(p,session){if(current!=='4인 3목'||ttSession!==session||finishText||st.turn!==p)return;let spots=st.board.map((v,j)=>v===-1?j:-1).filter(x=>x>=0);if(!spots.length){finish(null,'판이 가득 찼습니다.');render();return}let ai=null;for(let x of spots){let b=[...st.board];b[x]=p;if(ttWinner(b,x,p)){ai=x;break}}if(ai===null){for(let x of spots){let b=[...st.board];b[x]=0;if(ttWinner(b,x,0)){ai=x;break}}}if(ai===null)ai=pick(spots);st.board[ai]=p;logit(`AI ${p}가 ${String.fromCharCode(65+ai%5)}${Math.floor(ai/5)+1}에 착수`);if(ttWinner(st.board,ai,p))finish(false,`AI ${p}가 먼저 세 돌 연결`);else if(st.board.every(v=>v!==-1))finish(null,'25칸이 모두 찼습니다.');else st.turn=p<3?p+1:0;render();if(!finishText&&st.turn!==0)setTimeout(()=>ttAIPlace(st.turn,session),500)}
ttDraw=function(){const syms=['◆','●','▲','■'],cls=['you','bot1','bot2','bot3'];stage(`${exBar(['4인 대전 · 나 + AI 3명',st.turn===0?'내 차례':`AI ${st.turn} 생각 중…`])}<div class="info">${st.turn===0?'빈 칸을 선택하세요.':'AI가 차례로 수를 놓습니다. 다음 참가자의 말을 확인하세요.'}</div>${exBoard(5,i=>`<button class="ex-cell tt-cell ${st.board[i]===-1?'':cls[st.board[i]]}" onclick="ttMove(${i})" ${st.board[i]!==-1||finishText||st.turn!==0?'disabled':''}>${st.board[i]===-1?'':syms[st.board[i]]}</button>`)}<p class="small">나 ◆ · AI 1 ● · AI 2 ▲ · AI 3 ■</p>`,`<p class="muted">가로·세로·대각선으로 세 돌을 먼저 잇습니다. AI 세 명이 순서대로 행동합니다.</p>`) };

// 블라인드 오목: AI response should be visible as a separate turn.
let gmSession=0;
const _gmInitOriginal=gmInit;
gmInit=function(){gmSession++;_gmInitOriginal();st.turn=0};
gmMove=function(i){if(finishText||st.turn!==0||st.board[i]!==null)return;const color=randint(gmColors.length);st.board[i]={owner:0,color};st.moves.push({i,owner:0});st.last=i;if(gmWin(st.board,i,0)){finish(true,'다섯 개 연속 배치 성공');render();return}if(st.moves.length===225){finish(null,'무승부');render();return}st.turn=1;render();const id=gmSession;setTimeout(()=>{if(current!=='블라인드 오목'||gmSession!==id||st.turn!==1||finishText)return;let j=gmPickAI();st.board[j]={owner:1,color:randint(gmColors.length)};st.moves.push({i:j,owner:1});st.last=j;logit(`AI가 ${String.fromCharCode(65+j%15)}${Math.floor(j/15)+1}에 착수`);if(gmWin(st.board,j,1))finish(false,'AI가 다섯 개 연결');else st.turn=0;render()},650)};
gmDraw=function(){stage(`${exBar(['15×15 블라인드 오목',st.turn===0?'내 차례':'AI 생각 중…',`착수 ${st.moves.length}수`])}<div class="info">${st.turn===0?'둘 위치를 기억하며 돌을 놓으세요.':'AI가 돌을 놓습니다. 다음 수를 확인하세요.'}</div>${exBoard(15,i=>`<button class="ex-cell gm-cell ${st.last===i?'last':''}" title="${String.fromCharCode(65+i%15)}${Math.floor(i/15)+1}" onclick="gmMove(${i})" ${st.board[i]||finishText||st.turn!==0?'disabled':''}>${st.board[i]?`<span class="gm-stone" style="background:${gmColors[st.board[i].color]}"></span>`:''}</button>`)}<p class="small">돌의 색이 소유자를 의미하지 않습니다. 마지막 착수에 금색 테두리가 나타납니다.</p>`,`<p class="muted">원작과 달리 3·3, 4·4 금수는 미적용입니다.</p>`) };

// 큐브 세기: acknowledge answer and show feedback, do not jump directly to next puzzle.
const _ccInitOriginal=ccInit;
ccInit=function(){_ccInitOriginal();st.phase='answer';st.feedback=''};
ccSubmit=function(){if(finishText||st.phase!=='answer'||Date.now()<st.blocked)return;let el=$('#ex-answer');if(!el||el.value==='')return;let guess=Number(el.value);if(guess===st.correct){st.score++;st.feedback=`정답입니다! 정육면체 ${st.correct}개`;st.phase='review';logit(`${st.round}번 문제 정답: ${st.correct}개`);render()}else{st.blocked=Date.now()+20000;st.feedback=`${guess}개는 오답입니다. 20초 후 재도전하세요.`;logit(st.feedback);render();setTimeout(()=>{if(current==='큐브 세기'&&!finishText&&Date.now()>=st.blocked)render()},20100)}};
function ccNext(){if(st.phase!=='review')return;if(st.round>=5){finish(true,'5문제 정답!');render();return}st.round++;ccNew();st.phase='answer';st.feedback='';render()}
ccDraw=function(){let n=st.size,columns=st.heights.map(h=>`<div class="cc-column" style="--h:${h}">${Array.from({length:h},(_,k)=>`<i style="--level:${k}"></i>`).join('')}</div>`).join('');stage(`${exBar([`문제 ${st.round}/5`,`정답 ${st.score}`])}<div class="cc-scene" style="--size:${n}">${columns}</div>${st.feedback?`<div class="${st.phase==='review'?'result':'info'}">${txt(st.feedback)}</div>`:''}${st.phase==='review'?`<div class="round-controls">${action(st.round===5?'완료 확인':'다음 문제','ccNext()')}</div>`:`<div class="toolbar"><input id="ex-answer" class="inp" type="number" min="1" placeholder="정육면체 개수"><button class="btn" onclick="ccSubmit()" ${Date.now()<st.blocked?'disabled':''}>답 제출</button></div>`}`,`<p class="muted">겹쳐 보이는 큐브의 아래층까지 세어 답을 제출하세요. 정답 확인 뒤 다음 문제로 진행합니다.</p>`) };

// 네모 세기: keep solved puzzle visible until user explicitly moves on.
const _rcInitOriginal=rcInit;
rcInit=function(){_rcInitOriginal();st.phase='answer';st.feedback=''};
rcSubmit=function(){if(finishText||st.phase==='review')return;let el=$('#ex-answer');if(!el||el.value==='')return;let guess=Number(el.value);if(guess===st.answer){st.score++;st.phase='review';st.feedback=`정답! 조건을 만족하는 직사각형은 ${st.answer}개입니다.`;logit(`${st.round}번 문제 정답 ${st.answer}개`)}else{st.score=Math.max(0,st.score-1);st.feedback=`${guess}개는 오답입니다. 다시 확인해보세요.`;logit(st.feedback)}render()};
function rcNext(){if(st.phase!=='review')return;if(st.score>=2){finish(true,'두 문제 정답!');render();return}st.round++;rcNew();st.phase='answer';st.feedback='';render()}
rcDraw=function(){stage(`${exBar([`정답 ${st.score}/2`,`목표 합 ${st.target}`])}<div class="info">모든 크기의 직사각형 중 합이 ${st.target}인 영역의 개수는?</div>${exBoard(5,i=>`<div class="ex-cell rc-cell">${st.grid[i]||'·'}</div>`)}${st.feedback?`<div class="${st.phase==='review'?'result':'info'}">${txt(st.feedback)}</div>`:''}${st.phase==='review'?action(st.score>=2?'완료 확인':'다음 문제','rcNext()'):`<div class="toolbar"><input id="ex-answer" type="number" min="0" class="inp" placeholder="개수">${action('답 제출','rcSubmit()')}</div>`}`,`<p class="muted">직사각형 개수를 직접 찾고, 정답 확인 뒤 다음 판으로 진행합니다.</p>`) };
